-- Row-level security: the tenant boundary is enforced by Postgres, not by application code.
-- The app sets `app.user_id` per connection (Supabase derives it from the JWT via auth.uid()).
--
-- The per-table block below is written out in full rather than generated by a DO loop. A loop is
-- shorter, but a reviewer cannot see which tables are protected without executing it, and the CI
-- check in scripts/check_schema.py could not verify it statically either.

create or replace function app_current_user() returns uuid
language sql stable as $$
  select nullif(current_setting('app.user_id', true), '')::uuid
$$;

create or replace function is_org_member(target uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from org_members m
     where m.org_id = target and m.user_id = app_current_user()
  )
$$;

create or replace function is_org_admin(target uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from org_members m
     where m.org_id = target and m.user_id = app_current_user()
       and m.role in ('owner', 'admin')
  )
$$;

alter table business_profiles enable row level security;
alter table business_profiles force row level security;
create policy business_profiles_read   on business_profiles for select using (is_org_member(org_id));
create policy business_profiles_write  on business_profiles for insert with check (is_org_member(org_id));
create policy business_profiles_update on business_profiles for update using (is_org_member(org_id)) with check (is_org_member(org_id));
create policy business_profiles_delete on business_profiles for delete using (is_org_admin(org_id));
