alter table organizations enable row level security;
alter table organizations force row level security;
create policy organizations_read  on organizations for select using (is_org_member(id));
create policy organizations_admin on organizations for update using (is_org_admin(id)) with check (is_org_admin(id));

alter table org_members enable row level security;
alter table org_members force row level security;
create policy org_members_read  on org_members for select using (is_org_member(org_id));
create policy org_members_admin on org_members for all    using (is_org_admin(org_id)) with check (is_org_admin(org_id));

alter table app_users enable row level security;
create policy app_users_self on app_users for select
  using (
    id = app_current_user()
    or exists (select 1 from org_members m where m.user_id = app_users.id and is_org_member(m.org_id))
  );

-- Audit logs are append-only. No update or delete policy is created on purpose, and the grants are
-- revoked, so the table is immutable to every application role.
alter table audit_logs enable row level security;
create policy audit_logs_read  on audit_logs for select using (org_id is null or is_org_member(org_id));
create policy audit_logs_write on audit_logs for insert with check (true);
revoke update, delete on audit_logs from public;
